<script>
(() => { const rows=document.getElementById('documentRows'), add=document.getElementById('addDocument'); let next=1; add.addEventListener('click',()=>{const source=rows.querySelector('.document-row'); const clone=source.cloneNode(true); clone.querySelectorAll('[name]').forEach(el=>{el.name=el.name.replace(/documents\[\d+\]/,`documents[${next}]`); if(el.type==='file'||el.type==='checkbox') el.checked=false, el.value=el.type==='file'?'':el.value; else el.value='';}); clone.querySelectorAll('[id]').forEach(el=>el.id=el.id.replace(/\d+$/,String(next))); clone.querySelectorAll('label[for]').forEach(el=>el.htmlFor=el.htmlFor.replace(/\d+$/,String(next))); clone.querySelector('.remove-document').classList.remove('d-none'); rows.appendChild(clone); next++;}); rows.addEventListener('click',e=>{if(e.target.closest('.remove-document'))e.target.closest('.document-row').remove();}); })();
document.querySelectorAll('.scope-choice').forEach(box=>box.addEventListener('change',()=>{if(document.querySelectorAll('.scope-choice:checked').length>3){box.checked=false;alert('Maksimal pilih tiga ruang lingkup.')}}));
</script>
